package ru.otus.jdbc.mapper;import java.lang.reflect.Field;import java.util.List;import java.util.stream.Collectors;@SuppressWarnings({"java:S1488", "java:S3740"})public class EntitySQLMetaDataImpl implements EntitySQLMetaData {    private final EntityClassMetaData metaData;    public EntitySQLMetaDataImpl(EntityClassMetaData metadata) {        this.metaData = metadata;    }    @Override    public String getSelectAllSql() {        return String.format("select * from %s ", metaData.getName());    }    @Override    public String getSelectByIdSql() {        return String.format("select * from %1s where %2s = ?", metaData.getName(), metaData.getIdField().getName());    }    @Override    public String getInsertSql() {        List<Field> fields = metaData.getFieldsWithoutId();        String fieldNames = fields                .stream()                .map(Field::getName)                .collect(Collectors.joining(", ", "(", ")"));        String fieldValues = fields                .stream()                .map(field -> "?")                .collect(Collectors.joining(", ", "(", ")"));        return String.format("insert into %1s%2s values %3s", metaData.getName(), fieldNames, fieldValues);    }    @Override    public String getUpdateSql() {        List<Field> fields = metaData.getAllFields();        String fieldNames = fields                .stream()                .map(field->field.getName() + " = ?")                .collect(Collectors.joining(", "));        String format = String.format("update %s set %s where %s = ?", metaData.getName(), fieldNames, metaData.getIdField().getName());        return format;    }}